def("src/core/color.js", function (req) {
/** Colour helpers: WCAG relative luminance and contrast ratio. */

/** @param {string} hex `#RRGGBB` @returns {number} */
function luminance(hex) {
  const m = /^#([0-9a-f]{6})$/i.exec(hex);
  if (!m) throw new Error(`Not a #RRGGBB colour: ${hex}`);
  const [r, g, b] = [0, 2, 4].map((i) => {
    const c = parseInt(m[1].slice(i, i + 2), 16) / 255;
    return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

/** @param {string} a @param {string} b @returns {number} contrast ratio, 1 to 21 */
function contrast(a, b) {
  const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
}

/**
 * The first colour that reads as text on `background` (WCAG AA, 4.5:1), or the theme's dark text.
 * @param {string[]} candidates @param {string} background
 */
function firstReadable(candidates, background) {
  return candidates.find((c) => contrast(c, background) >= 4.5) || '#2B2B2B';
}
return { luminance, contrast, firstReadable };
});
def("src/core/dates.js", function (req) {
/** Dates on the person's own calendar (local time). Kinpital runs in real time: a bill due on the 10th is due on the 10th. */

const DAY = 86400000;

/** @param {Date} d */
function startOfDay(d) {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

/** @param {Date} d @param {number} n */
function addDays(d, n) {
  const x = startOfDay(d);
  x.setDate(x.getDate() + n);
  return x;
}

/** Whole calendar days from `from` to `to` (negative when `to` is earlier). Rounds, so a DST change does not shift it. */
function daysBetween(from, to) {
  return Math.round((startOfDay(to).getTime() - startOfDay(from).getTime()) / DAY);
}

/** The next date (today included) that falls on `day` of the month; short months use their last day. */
function nextMonthDay(now, day) {
  const today = startOfDay(now);
  for (let k = 0; k < 2; k++) {
    const y = today.getFullYear();
    const m = today.getMonth() + k;
    const last = new Date(y, m + 1, 0).getDate();
    const d = new Date(y, m, Math.min(day, last));
    if (d >= today) return d;
  }
  return today;
}

/** @param {number} days from today */
function dueLabel(days) {
  if (days < 0) return `${-days} day${days === -1 ? '' : 's'} late`;
  if (days === 0) return 'today';
  if (days === 1) return 'tomorrow';
  return `in ${days} days`;
}

/** @param {Date} d e.g. "Dec 10" */
function shortDate(d) {
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}

/** @param {Date} d e.g. "Mon, Nov 23 · 6:40 PM" */
function clockLine(d) {
  const day = d.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
  const time = d.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
  return `${day} · ${time}`;
}
return { startOfDay, addDays, daysBetween, nextMonthDay, dueLabel, shortDate, clockLine };
});
def("src/core/finance.js", function (req) {
/** One person's money at a glance: what they have, what they owe, what comes next. */
const { convert, sum } = req("src/core/money.js");
const { daysBetween, nextMonthDay } = req("src/core/dates.js");

/**
 * @param {any} data the finance state (see src/screen/sample.js for its shape)
 * @param {string} personId
 * @param {Date} now
 * @param {string} currency the currency totals are shown in
 */
function summarize(data, personId, now, currency) {
  /** @param {any[]} list */
  const mine = (list) => list.filter((x) => x.owner === personId);
  /** @param {number} amount @param {string} from */
  const to = (amount, from) => convert(amount, from, currency, data.rates);

  const accounts = mine(data.accounts);
  const cards = mine(data.cards);
  const loans = mine(data.loans);
  const assets = mine(data.assets);
  const income = mine(data.income);

  const cash = sum(accounts.map((a) => to(a.balance, a.currency)));
  const owned = sum(assets.map((a) => to(a.value, a.currency)));
  const debt = sum(cards.map((c) => to(c.bill, c.currency))) + sum(loans.map((l) => to(l.remaining, l.currency)));

  const upcoming = [
    ...cards.map((c) => ({ kind: 'card', bank: c.bank, label: 'Card bill', amount: -c.bill, currency: c.currency, date: c.due })),
    ...loans.map((l) => ({ kind: 'loan', bank: l.bank, label: 'Loan installment', amount: -l.installment, currency: l.currency, date: l.due })),
    ...income.map((i) => ({ kind: 'income', bank: i.bank, label: 'Payday', amount: i.amount, currency: i.currency, date: nextMonthDay(now, i.payday) })),
  ]
    .map((u) => ({ ...u, days: daysBetween(now, u.date) }))
    .sort((a, b) => a.days - b.days);

  const activity = mine(data.activity).sort((a, b) => b.date.getTime() - a.date.getTime());

  return {
    accounts, cards, loans, assets, income, upcoming, activity,
    cash, owned, debt,
    netWorth: cash + owned - debt,
    monthChange: to(data.monthChange[personId] || 0, data.rates.base),
  };
}
return { summarize };
});
def("src/core/money.js", function (req) {
/** Money: formatting and currency conversion. */

/** @typedef {{ base: string, perUnit: Record<string, number> }} Rates  value of 1 unit of each currency, in `base` */

/**
 * @param {number} amount
 * @param {string} currency ISO 4217
 * @param {{ sign?: boolean }} [opts] sign: show + on positive amounts
 */
function formatMoney(amount, currency, opts = {}) {
  const fmt = new Intl.NumberFormat('en-US', { style: 'currency', currency, signDisplay: opts.sign ? 'exceptZero' : 'auto' });
  return fmt.format(Math.abs(amount) < 0.005 ? 0 : amount);
}

/** @param {number} amount @param {string} from @param {string} to @param {Rates} rates */
function convert(amount, from, to, rates) {
  if (from === to) return amount;
  const a = rates.perUnit[from];
  const b = rates.perUnit[to];
  if (!a || !b) throw new Error(`No rate for ${from} or ${to}`);
  return (amount * a) / b;
}

/** @param {number[]} values */
function sum(values) {
  return values.reduce((t, v) => t + v, 0);
}
return { formatMoney, convert, sum };
});
def("src/screen/bank-theme.js", function (req) {
/** Inside a bank the whole screen takes that bank's colours: only theme variables change, never component styles. */
const { contrast, firstReadable } = req("src/core/color.js");

const VARS = ['--accent', '--accent-hover', '--accent-deep', '--accent-tint', '--on-accent', '--bg', '--bg-glow-1', '--bg-glow-2', '--shadow-accent', '--focus'];

/** @param {string} hex @param {number} alpha */
function rgba(hex, alpha) {
  const n = parseInt(hex.slice(1), 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${alpha})`;
}

/**
 * @param {HTMLElement} root
 * @param {{ colors: { primary: string, secondary: string, surface: string, accent: string, onAccent: string } } | null | undefined} bank
 *   null: back to the Kinpital theme
 */
function applyBankTheme(root, bank) {
  for (const v of VARS) root.style.removeProperty(v);
  if (!bank) return;
  const c = bank.colors;
  const deep = firstReadable([c.primary, c.accent, c.secondary, c.onAccent], c.surface);
  /** @type {Record<string, string>} */
  const set = {
    '--accent': c.accent,
    '--accent-hover': c.accent,
    '--accent-deep': deep,
    '--accent-tint': rgba(c.primary, contrast(c.primary, '#FFFFFF') < 2 ? 0.28 : 0.12),
    '--on-accent': c.onAccent,
    '--bg': c.surface,
    '--bg-glow-1': rgba(c.secondary, 0.35),
    '--bg-glow-2': rgba(c.primary, 0.14),
    '--shadow-accent': `0 8px 20px ${rgba(c.primary, 0.3)}`,
    '--focus': deep,
  };
  for (const k of Object.keys(set)) root.style.setProperty(k, set[k]);
}
return { rgba, applyBankTheme };
});
def("src/screen/common.js", function (req) {
/** Pieces shared by the views. */
const { h, logo } = req("src/screen/dom.js");
const { icon } = req("src/screen/icons.js");
const { formatMoney } = req("src/core/money.js");
const { bankById } = req("src/core/banks.js");
const { dueLabel, shortDate } = req("src/core/dates.js");

/**
 * @typedef {object} Ctx
 * @property {{ person: string, view: { name: string, bank?: string }, hidden: boolean, currency: string, palette: string, now: Date, info: boolean }} state
 * @property {any} data
 * @property {(view: { name: string, bank?: string }) => void} go
 * @property {(patch: object) => void} set
 * @property {(message: string) => void} toast
 */

const HIDDEN = '••••••';

/** @param {Ctx} ctx @param {number} amount @param {string} currency @param {{ sign?: boolean }} [opts] */
function money(ctx, amount, currency, opts) {
  return ctx.state.hidden ? HIDDEN : formatMoney(amount, currency, opts);
}

/** @param {Ctx} ctx */
function person(ctx) {
  return ctx.data.people.find((/** @type {any} */ p) => p.id === ctx.state.person);
}

/** "Your" or "Bia's" @param {Ctx} ctx */
function possessive(ctx) {
  const p = person(ctx);
  return p.kind === 'user' ? 'Your' : `${p.name}'s`;
}

/** @param {Ctx} ctx @param {string} title @param {any} [right] */
function topBar(ctx, title, right) {
  return h('header', { class: 'topbar' },
    h('button', { class: 'icon-btn', type: 'button', 'aria-label': 'Back', onclick: () => ctx.go({ name: 'home' }) }, icon('back')),
    h('h1', { class: 'topbar-title' }, title),
    right || h('span', { class: 'topbar-space' }));
}

/** @param {string} text */
function sectionTitle(text) {
  return h('h2', { class: 'section-title' }, text);
}

/** One line of activity. @param {Ctx} ctx @param {any} t */
function activityRow(ctx, t) {
  const bank = bankById(t.bank);
  return h('li', { class: 'row' },
    logo(t.bank, 32),
    h('span', { class: 'row-text' },
      h('span', { class: 'row-main' }, t.text),
      h('span', { class: 'row-sub' }, `${bank ? bank.name : ''} · ${shortDate(t.date)}`)),
    h('span', { class: `amount ${t.amount > 0 ? 'in' : ''}` }, money(ctx, t.amount, t.currency, { sign: true })));
}

/** One bill, installment or payday. @param {Ctx} ctx @param {any} u */
function upcomingRow(ctx, u) {
  const bank = bankById(u.bank);
  const late = u.days < 0;
  return h('li', null,
    h('button', { class: `row row-btn ${late ? 'late' : ''}`, type: 'button', onclick: () => ctx.go({ name: 'bank', bank: u.bank }) },
      logo(u.bank, 32),
      h('span', { class: 'row-text' },
        h('span', { class: 'row-main' }, `${bank ? bank.name : ''} · ${u.label}`),
        h('span', { class: 'row-sub' },
          late ? h('span', { class: 'late-tag' }, 'Late') : null,
          late ? ` ${dueLabel(u.days)}` : `${shortDate(u.date)} · ${dueLabel(u.days)}`)),
      h('span', { class: `amount ${u.amount > 0 ? 'in' : ''}` }, money(ctx, u.amount, u.currency, { sign: u.amount > 0 }))));
}

/** @param {string} text */
function empty(text) {
  return h('p', { class: 'empty muted' }, text);
}
return { HIDDEN, money, person, possessive, topBar, sectionTitle, activityRow, upcomingRow, empty };
});
def("src/screen/dom.js", function (req) {
/** A tiny element builder. Text always goes in as text (names come from Kindroid), never as HTML. */

/**
 * @param {string} tag
 * @param {Record<string, any> | null} [props] class, style, on<event>, or any attribute (true = present, false/null = absent)
 * @param {...any} children nodes, strings, numbers, arrays; null and false are skipped
 * @returns {HTMLElement}
 */
function h(tag, props, ...children) {
  const el = document.createElement(tag);
  if (props) {
    for (const key of Object.keys(props)) {
      const v = props[key];
      if (v == null || v === false) continue;
      if (key === 'class') el.className = v;
      else if (key === 'style') el.style.cssText = v;
      else if (key.startsWith('on')) el.addEventListener(key.slice(2), v);
      else el.setAttribute(key, v === true ? '' : String(v));
    }
  }
  append(el, children);
  return el;
}

/** @param {Node} el @param {any[]} children */
function append(el, children) {
  for (const c of children) {
    if (c == null || c === false) continue;
    if (Array.isArray(c)) append(el, c);
    else el.appendChild(c instanceof Node ? c : document.createTextNode(String(c)));
  }
}

/** @param {string} bankId @param {number} size */
function logo(bankId, size) {
  return h('img', { class: 'logo', src: `assets/banks/${bankId}.svg`, alt: '', width: size, height: size });
}
return { h, logo };
});
